-- Taiwan 2025 match query (read-only). relay sha256 947c8ebe58654a2bc9df273a8b6c2d0a0d811293806d2503c57b4bf14c342e0a
WITH p AS (SELECT (e->>0)::int seq, e->>1 city, e->>2 cat, e->>3 nm, e->>4 mark
             FROM jsonb_array_elements('[[1, "Taipei", "Three Stars", "Le Palais", ""], [2, "Taipei", "Three Stars", "Ta\u00efrroir", ""], [3, "Taichung", "Three Stars", "JL Studio", ""], [4, "Taipei", "Two Stars", "A", "PROMOTED"], [5, "Taipei", "Two Stars", "Eika", "PROMOTED"], [6, "Taipei", "Two Stars", "L''Atelier de Jo\u00ebl Robuchon", ""], [7, "Taipei", "Two Stars", "logy", ""], [8, "Taipei", "Two Stars", "Molino de Urd\u00e1niz", ""], [9, "Taipei", "Two Stars", "Mudan", ""], [10, "Taipei", "Two Stars", "Yu Kapo", "PROMOTED"], [11, "Taipei", "One Star", "A Cut", ""], [12, "Taipei", "One Star", "Ad Astra", ""], [13, "Taipei", "One Star", "aMaze", "NEW"], [14, "Taipei", "One Star", "Ban Bo", ""], [15, "Taipei", "One Star", "Chuan Ya", "NEW"], [16, "Taipei", "One Star", "Circum-", ""], [17, "Taipei", "One Star", "de nuit", ""], [18, "Taipei", "One Star", "FRASSI", "PROMOTED"], [19, "Taipei", "One Star", "Fujin Tree Taiwanese Cuisine & Champagne (Songshan)", ""], [20, "Taipei", "One Star", "Golden Formosa", ""], [21, "Taipei", "One Star", "Hosu", "PROMOTED"], [22, "Taipei", "One Star", "Impromptu by Paul Lee", ""], [23, "Taipei", "One Star", "INITA", ""], [24, "Taipei", "One Star", "Ken Anhe", ""], [25, "Taipei", "One Star", "Kitcho", ""], [26, "Taipei", "One Star", "La Vie by Thomas B\u00fchner", "PROMOTED"], [27, "Taipei", "One Star", "Ming Fu", ""], [28, "Taipei", "One Star", "Mipon", ""], [29, "Taipei", "One Star", "Motoichi", "NEW"], [30, "Taipei", "One Star", "Mountain and Sea House", ""], [31, "Taipei", "One Star", "NOBUO", ""], [32, "Taipei", "One Star", "Paris 1930 de Hideki Takayama", ""], [33, "Taipei", "One Star", "Sens", ""], [34, "Taipei", "One Star", "Shin Yeh Taiwanese Signature", ""], [35, "Taipei", "One Star", "Sushi Akira", ""], [36, "Taipei", "One Star", "Sushi Kajin", "NEW"], [37, "Taipei", "One Star", "Sushi Ryu", ""], [38, "Taipei", "One Star", "Sushiyoshi", ""], [39, "Taipei", "One Star", "T+T", ""], [40, "Taipei", "One Star", "The Guest House", ""], [41, "Taipei", "One Star", "Tien Hsiang Lo", ""], [42, "Taipei", "One Star", "Wok by O''BOND", ""], [43, "Taipei", "One Star", "Ya Ge", ""], [44, "Taipei", "One Star", "ZEA", ""], [45, "Taichung", "One Star", "Fleur de Sel", ""], [46, "Taichung", "One Star", "L''Atelier par Yao", ""], [47, "Taichung", "One Star", "Oretachi No Nikuya", ""], [48, "Taichung", "One Star", "Sur-", ""], [49, "Taichung", "One Star", "YUENJI", ""], [50, "Kaohsiung", "One Star", "GEN", ""], [51, "Kaohsiung", "One Star", "HAILI", ""], [52, "Kaohsiung", "One Star", "Sho", ""], [53, "Kaohsiung", "One Star", "the FRONT HOUSE", "PROMOTED"], [54, "Taipei", "Green Star", "EMBERS", ""], [55, "Taipei", "Green Star", "Hosu", ""], [56, "Taipei", "Green Star", "Little Tree Food (Da''an Road)", ""], [57, "Taipei", "Green Star", "Mountain and Sea House", ""], [58, "Taipei", "Green Star", "Yangming Spring (Shilin)", ""], [59, "Taichung", "Green Star", "Tu Pang", "NEW"], [60, "Kaohsiung", "Green Star", "Thomas Chien", ""]]'::jsonb) e),
  c(city, city_id) AS (VALUES ('Taipei','ci_39139f000b'),('Taichung','ci_6d39e9b076'),('Kaohsiung','ci_c65258d965')),
  pk AS (SELECT p.*, c.city_id, norm_key(p.nm) k1, norm_key(regexp_replace(p.nm, '\s*\([^)]*\)\s*$', '')) k2 FROM p JOIN c USING (city)),
  vk AS (SELECT v.id, v.city_id, v.name, v.status, coalesce(v.norm_key, norm_key(v.name)) k1,
                norm_key(regexp_replace(v.name, '\s*\([^)]*\)\s*$', '')) k2
           FROM venues v WHERE v.city_id IN ('ci_39139f000b','ci_6d39e9b076','ci_c65258d965')),
  t1 AS (SELECT pk.seq, count(*) n, min(vk.id) vid FROM pk JOIN vk ON vk.city_id=pk.city_id AND vk.k1=pk.k1 GROUP BY pk.seq),
  t2 AS (SELECT pk.seq, count(*) n, min(vk.id) vid FROM pk JOIN vk ON vk.city_id=pk.city_id AND vk.k2=pk.k2 GROUP BY pk.seq),
  r AS (SELECT pk.seq, pk.city, pk.cat, pk.nm, pk.mark,
          CASE WHEN t1.n=1 THEN t1.vid WHEN t1.n IS NULL AND t2.n=1 THEN t2.vid END vid,
          CASE WHEN t1.n=1 THEN 't1' WHEN t1.n IS NULL AND t2.n=1 THEN 't2' WHEN coalesce(t1.n,t2.n,0)>1 THEN 'multi' ELSE 'none' END how
        FROM pk LEFT JOIN t1 USING (seq) LEFT JOIN t2 USING (seq))
SELECT r.seq, r.city, r.cat, r.nm, r.mark, r.how, r.vid, v.name vname, v.status,
  (SELECT string_agg(a.id||':'||a.category||':'||coalesce(left(a.source_url,40),'null'), ' ; ') FROM awards a
     WHERE a.venue_id=r.vid AND a.source_id='michelin' AND a.year=2025) m2025,
  (SELECT string_agg(a.category, ',') FROM awards a WHERE a.venue_id=r.vid AND a.source_id='michelin' AND a.year=2026) m2026
FROM r LEFT JOIN venues v ON v.id=r.vid ORDER BY r.seq;
